    result = merge_with(lambda vals: sorted(vals), {1: 3, 2: 1}, {1: 1, 3: 2})
    assert result == {1: [1, 3], 2: [1], 3: [2]}


def test_merge_with_values_are_lists():
    seen = {}

    def capture(vals):
        seen.update(vals if isinstance(vals, dict) else {})
        return list(vals)

    result = merge_with(capture, {1: 'a'}, {1: 'b'})
    assert result == {1: ['a', 'b']}


